import math
from math import pi,sqrt
N=[]
def mcq(t,l,q,right,wrongs,w,multi=None):
    N.append({'t':t,'l':l,'type':'mcq','q':q,'o':[right]+wrongs,'w':w})
def S(t,l,q,v,u,w,tol=0.02):
    N.append({'t':t,'l':l,'type':'short','q':q,'num':{'v':v,'u':u,'tol':tol},'w':w})
def SN(t,l,q,v,w,tol=0.0):  # unitless number
    N.append({'t':t,'l':l,'type':'short','q':q,'num':{'v':v,'tol':tol},'w':w})
def T(t,l,q,acc,w):
    N.append({'t':t,'l':l,'type':'short','q':q,'text':acc,'w':w})
def O(t,l,q,items,w):
    N.append({'t':t,'l':l,'type':'order','q':q,'items':items,'w':w})
def M(t,l,q,pairs,w):
    N.append({'t':t,'l':l,'type':'match','q':q,'pairs':pairs,'w':w})

