# ---------- ordering ----------
O('hist',2,'Put these in order of when they did their best-known work, earliest first.',['Volta (voltaic pile)','Ohm (V = IR)','Kirchhoff (circuit laws)','Boole (algebra of logic)','Hertz (radio waves)'],'1800, 1827, 1845, 1854, 1887.')
O('circ',2,'Order these resistor networks by equivalent resistance, smallest first.',['three 30 Ω in parallel','two 30 Ω in parallel','one 30 Ω alone','two 30 Ω in series'],'10 Ω, 15 Ω, 30 Ω, 60 Ω.')
O('diode',2,'Order by forward voltage drop, smallest first.',['one silicon diode','two silicon diodes in series','red LED','blue LED'],'About 0.7 V, 1.4 V, 1.9 V, 3.2 V.')
O('logic',2,'Order these values from smallest to largest.',['binary 1100','decimal 13','binary 1110','decimal 17'],'12, 13, 14, 17.')
O('virpe',2,'Order these supplies by power delivered, smallest first.',['3.3 V at 0.5 A','5 V at 1 A','12 V at 1 A','9 V at 2 A'],'1.65 W, 5 W, 12 W, 18 W.')
O('diode',2,'Put the steps for sizing an LED resistor in order.',['Subtract the LED drop from the supply voltage','Divide by the desired current','Round up to a standard value','Check the resistor’s power rating'],'R = (Vs − Vf)/I, round up, then check P = I²R.')
O('circ',2,'Put the steps for solving a series-parallel network in order.',['Combine resistors until one remains','Find the total current from V/R','Work back to find each group’s voltage','Check that power in equals power out'],'Reduce, find I, expand, verify.')
# ---------- matching ----------
M('hist',2,'Match each scientist to the contribution.',[['Volta','first chemical battery'],['Ohm','V = IR'],['Kirchhoff','loop and node laws'],['Boole','algebra of logic'],['Coulomb','force between charges']],'')
M('virpe',1,'Match each unit to its quantity.',[['ohm','resistance'],['coulomb','charge'],['watt','power'],['farad','capacitance'],['tesla','magnetic flux density']],'')
M('ctrl',2,'Match each device to its job.',[['fuse','melts once on overcurrent'],['GFCI','protects people from ground leakage'],['relay','small current switches a separate circuit'],['circuit breaker','trips and can be reset'],['DPDT switch','reverses a motor when cross-wired']],'')
M('logic',2,'Match each gate to its output behavior.',[['AND','1 only when both inputs are 1'],['OR','1 when at least one input is 1'],['NOR','1 only when both inputs are 0'],['XOR','1 when the inputs differ'],['NAND','0 only when both inputs are 1']],'')
M('virpe',1,'Match each resistor color to its digit.',[['red','2'],['orange','3'],['green','5'],['violet','7'],['white','9']],'')
M('sym',2,'Match each rule to its form.',[['modus ponens','P → Q, P ∴ Q'],['modus tollens','P → Q, ~Q ∴ ~P'],['hypothetical syllogism','P → Q, Q → R ∴ P → R'],['disjunctive syllogism','P ∨ Q, ~P ∴ Q']],'')
M('mag',2,'Match each scientist to the discovery.',[['Ørsted','current deflects a compass'],['Ampère','parallel currents attract or repel'],['Faraday','electromagnetic induction'],['Tesla','AC induction motor']],'')
